#include "mediaengine/scanengine.h"
#include "mediaengine/scancoordinator.h"
#include "mediaengineadapter.h"
#include "mediascanner.h"
#include <QCoreApplication>
#include <QDir>
#include <QFile>
#include <QTemporaryDir>
#include <QEventLoop>
#include <QTimer>
#include <QJsonDocument>
#include <QJsonArray>
#include <QJsonObject>
#include <QTextStream>
#include <QtEndian>
#include <atomic>
#include <stdexcept>
using namespace MediaEngine;
namespace {
void require(bool ok, const char *message) { if (!ok) throw std::runtime_error(message); }
template<typename T> void appendNumber(QByteArray &bytes, T value) { char encoded[sizeof(T)]; qToLittleEndian(value, encoded); bytes.append(encoded, sizeof(T)); }
QByteArray pmr(const QString &fileId, const QString &masterId) {
 QByteArray b; appendNumber<quint32>(b,0x7a9); appendNumber<qint32>(b,8); appendNumber<quint32>(b,1);
 b.append(QByteArray::fromHex(fileId.toLatin1().replace(".","")));
 QByteArray filename("take.mxf"), project("Completed PMR project");
 appendNumber<quint16>(b,filename.size()); b.append(filename); appendNumber<quint16>(b,project.size()); b.append(project);
 b.append(QByteArray::fromHex(masterId.toLatin1().replace(".",""))); appendNumber<quint32>(b,0); return b;
}
void write(const QString &path,const QByteArray &data) { QFile f(path); require(f.open(QIODevice::WriteOnly),"cannot write control"); require(f.write(data)==data.size(),"short control write"); }
QJsonObject describe(const ScanResult &s) {
 QJsonArray sources,rows;
 for(const auto &source:s.sources) sources.append(QJsonObject{{"path",source.snapshot->path},{"outcome",int(source.outcome)},{"readState",int(source.snapshot->readState)}});
 for(const auto &file:s.files) {
  const auto row=mediaEngineMediaFile(file,{},QStringLiteral("captured-test-volume"),QStringLiteral("test"));
  rows.append(QJsonObject{{"path",file.path},{"fileMobId",row.fileMobId},{"masterMobId",row.masterMobId},{"clipName",row.clipName},{"project",row.project},{"duration",row.durationDisplay()},{"fileMobIdObservationCount",file.evidence.observations(MediaProperty::FileMobId).size()},{"projectObservationCount",file.evidence.observations(MediaProperty::Project).size()}});
 }
 return {{"cancelled",s.cancelled},{"discoveryComplete",s.discoveryComplete},{"parsingComplete",s.parsingComplete},{"reconciliationComplete",s.reconciliationComplete},{"sources",sources},{"rows",rows}};
}
QJsonObject scannerRun(const QString &root, bool cancelAtFinalising) {
 MediaScanner scanner; QEventLoop loop; QTimer timeout; timeout.setSingleShot(true); bool timedOut=false,failed=false; QString failure;
 QStringList messages; QVector<::MediaFile> rows; std::atomic_bool triggered{false};
 QObject::connect(&timeout,&QTimer::timeout,&loop,[&]{timedOut=true; scanner.cancelScan();loop.quit();});
 QObject::connect(&scanner,&MediaScanner::scanFinalising,&scanner,[&]{if(cancelAtFinalising){triggered=true;scanner.cancelScan();}},Qt::DirectConnection);
 QObject::connect(&scanner,&MediaScanner::scanLogBatch,&scanner,[&](const QVector<LogMessage>&batch){
  for(const auto &message:batch){messages.append(message.message);if(!cancelAtFinalising&&message.message.startsWith(QStringLiteral("Scan complete:"))){triggered=true;scanner.cancelScan();}}
 },Qt::DirectConnection);
 QObject::connect(&scanner,&MediaScanner::scanFinished,&loop,[&](const QVector<::MediaFile>&result){rows=result;loop.quit();},Qt::QueuedConnection);
 QObject::connect(&scanner,&MediaScanner::scanFailed,&loop,[&](const QString&error){failed=true;failure=error;loop.quit();},Qt::QueuedConnection);
 MediaScanner::Options options; options.volumePaths={root}; scanner.startScan(options);timeout.start(5000);loop.exec();
 QJsonArray fields;for(const auto &row:rows)fields.append(QJsonObject{{"fileMobId",row.fileMobId},{"clipName",row.clipName},{"duration",row.durationDisplay()},{"capturedSessionCancelled",row.mediaEngineScan?row.mediaEngineScan->cancelled:false}});
 return {{"cancelHook",cancelAtFinalising?"scanFinalising DirectConnection":"scanLogBatch DirectConnection at final complete-message flush"},{"cancelTriggered",triggered.load()},{"timedOut",timedOut},{"failed",failed},{"failure",failure},{"rowCount",rows.size()},{"rows",fields},{"messages",QJsonArray::fromStringList(messages)}};
}
}
int main(int argc,char **argv) {
 QCoreApplication app(argc,argv);qRegisterMetaType<QVector<::MediaFile>>();qRegisterMetaType<QVector<LogMessage>>();
 try {
  require(app.arguments().size()==2,"need disposable specimen path"); const QString specimen=app.arguments()[1]; QTemporaryDir temp;require(temp.isValid(),"temp failed");
  const QString folder=temp.path()+"/Avid MediaFiles/MXF/1", path=folder+"/take.mxf"; require(QDir().mkpath(folder),"mkdir failed");require(QFile::copy(specimen,path),"copy failed");
  Cancellation normal;const auto baseline=ScanEngine{}.scan({{temp.path()},false},normal); require(baseline.files.size()==1,"baseline row count");
  const auto fileId=baseline.files[0].evidence.selected(MediaProperty::FileMobId).value.toString();const auto masters=baseline.files[0].evidence.selected(MediaProperty::MasterMobId).value.toStringList();require(!fileId.isEmpty()&&!masters.isEmpty(),"genuine baseline IDs missing");
  write(folder+"/index.pmr",pmr(fileId,masters.front()));Cancellation normalWithPmr;const auto baselineWithPmr=ScanEngine{}.scan({{temp.path()},false},normalWithPmr);Cancellation afterDatabase; ScanCallbacks databaseCallbacks;databaseCallbacks.progress=[&](int,int,const QString&current){if(current==path)afterDatabase.cancel();};const auto databaseCancel=ScanEngine{}.scan({{temp.path()},false},afterDatabase,databaseCallbacks);
  require(QFile::remove(folder+"/index.pmr"),"remove control failed");Cancellation beforeMatching;ScanCallbacks headerCallbacks;headerCallbacks.finalising=[&]{beforeMatching.cancel();};const auto headerCancel=ScanEngine{}.scan({{temp.path()},false},beforeMatching,headerCallbacks);
  QJsonObject report{{"specimenCopy",specimen},{"baseline",describe(baseline)},{"baselineWithConstructedPmr",describe(baselineWithPmr)},{"cancelAfterCompletePmrBeforeHeader",describe(databaseCancel)},{"cancelAfterCompleteHeaderBeforeMatching",describe(headerCancel)},{"productionScannerFinalisingCancel",scannerRun(temp.path(),true)},{"productionScannerLateCancelAtFinalLogFlush",scannerRun(temp.path(),false)}};
  QTextStream(stdout)<<QJsonDocument(report).toJson();return 0;
 } catch(const std::exception&e){QTextStream(stderr)<<e.what()<<'\n';return 1;}
}
